"daily-backup" = {
schedule_expression = {
"@@assign" = "cron(0 4 * * ? *)"
}
target_backup_vault_name = {
"@@assign" = "nist-compliant-vault"
}
lifecycle = {
delete_after_days = {
"@@assign" = 90
}
}
