"weekly-backup" = {
schedule_expression = {
"@@assign" = "cron(0 4 ? * SUN *)"
}
target_backup_vault_name = {
"@@assign" = "nist-compliant-vault"
}
lifecycle = {
move_to_cold_storage_after_days = {
"@@assign" = 30
}
delete_after_days = {
"@@assign" = 365
}
}
}
}
